"""Record the experiment contract before any predictive-model pilot."""
from pathlib import Path
import hashlib,json
import pandas as pd
BASE=Path(__file__).resolve().parent;ROOT=BASE.parent;OUT=BASE/'labeled_v1'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
labels=pd.read_parquet(OUT/'label_manifest.parquet');assert len(labels)==11200
assert labels.y.sum()==4480 and labels.mmsi.nunique()==2065
for region,g in labels.groupby('region'):
 assert len(g)==1400 and g.mmsi.nunique()==260
 for s,nw,nv in [('train',980,182),('val',210,39),('test',210,39)]:
  h=g[g.split==s];assert len(h)==nw and h.mmsi.nunique()==nv
 for _,h in g.groupby('mmsi'):assert len(h)<=20
groups={s:set(labels.loc[labels.split==s,'mmsi']) for s in ['train','val','test']}
assert not groups['train']&groups['val'] and not groups['train']&groups['test'] and not groups['val']&groups['test']
cap=json.loads((BASE/'planning/capacity.json').read_text())
regional={r:v for r,v in cap['training_only_physical_envelope'].items() if r!='all_train'}
physical={k:max(v[k]['p995'] for v in regional.values()) for k in ['acceleration_mps2','rot_deg_s','lateral_acceleration_mps2']}
config={'version':'balanced_global_v2_labeled_v1','status':'protocol_frozen_before_model_training','seed':20261026,
 'source_pool':{'windows':21600,'vessels_per_region':300,'windows_per_region':2700,'release':'../release_20261026','sha256':sha(ROOT/'release_20261026/selected_windows.parquet')},
 'labelled_core':{'windows':11200,'unique_mmsi':2065,'regions':8,'windows_per_region':1400,'vessels_per_region':260,'split_windows_per_region':{'train':980,'val':210,'test':210},'split_vessels_per_region':{'train':182,'val':39,'test':39},'normal_fraction':.6,'injected_anomaly_fraction':.4,'anomaly_type_totals':{str(k):int(v) for k,v in labels.loc[labels.y==1,'behavior_type'].value_counts().items()},'labels_sha256':sha(OUT/'label_manifest.parquet')},
 'label_semantics':{'y0':'No controlled behavior injection into the accepted source window; not human-annotated natural-normal ground truth','y1':'One controlled individual maneuver with a recorded observed effect','three_factors':'Individual behavior, observation corruption and normal collective motion are separate, composable factors, not mutually-exclusive labels','independence_unit':'Original source window / MMSI. Alternative feature or challenge views are never counted as extra independent observations'},
 'qualification':'Source in-motion prefix >=3 reports, >=3kn median and last prefix speed, measured and reported path >=500m, net displacement>=500m, reliable <=300s prefix intervals, >=3 post reports and >=180s observed maneuver. Both y0 sham and y1 are assigned only AFTER the same counterfactual feasibility/effect checks.',
 'generator':{'sha256':sha(BASE/'generator/maneuver_generator.py'),'profile':'cubic smoothstep 3u^2-2u^3','position_rule':'source position + cumulative actual-dt trapezoidal integral of augmented-minus-source velocity','observation_innovation':'Preserved as a vector before independent observation corruption','off_grid_onset':'Declared endpoint-average discrete bridge; no sub-report physical onset-time resolution claimed','parameter_policy':'Seeded continuous ranges, both turn directions, variable onset, duration, strength and sinusoid phase/period; actual applied parameters recorded','physical_budget_rule':'Per quantity max of each training-region p99.5; no validation or test observations calibrate the budget','physical_budget_values':physical,'budget_scope':'Reported-trajectory benchmark envelope. No ship-type-specific maneuvering limit claim.','rejection_policy':'Every accepted pool member, including future y0, passes the same checks before labels are assigned'},
 'observation_corruption':{'requested_probability':1/3,'assignment':'Within each region/split/behavior class, deterministic rounded count with at most one-report quota rounding; no performance-based choice','types':['teleport','speed_spike','drift'],'scopes':['target_only','neighbors_only','both'],'neighbor_fraction':.15,'order':'Behavior -> optional coherent group motion -> shared observation-corruption process -> recompute all kinematics and fields','unavailable_neighbors':'Record requested and effective corruption separately; never replace missing neighbor corruption with label-dependent target corruption'},
 'context_views':{'features_scene':'Targets globally disjoint. Train excludes all original source val/test target vessels; val excludes original test targets; test uses all available past scene reports. Background identities may recur.','features_strict':'All target and accessed context identities belong to the same original global MMSI split; actual cross-split identity intersection must be zero.','features_hard_scene':'Same accepted windows, labels, maneuver semantics, applied parameters, onset and observation perturbations as smooth scene; only the transition is a hard step. Hard-profile physical violations are diagnostic.','paired_group_scene':'Test-only paired challenge: target and its source-direction local cohort slow coherently, keeping original individual label. Rebuild physics after group motion and corruption.'},
 'mechanism_comparisons':{'raw':'7 raw incremental trajectory channels','plain_context':'16-channel ordinary unweighted neighborhood-mean context','plain_affine_context':'16-channel unweighted affine field control without reliability filtering/weighting','context':'16-channel reliability-gated target plus trusted weighted local affine field','parameter_control':'The three context groups have identical trainable parameter counts within a backbone. Raw7 changes the input layer and must report its parameter count separately. A separate capacity-matched raw control belongs in formal experiments.','training_augmentation':'PSA/statistical perturbation/consistency losses are OFF in this mechanism pilot and remain separate ablations'},
 'evaluation':{'primary_metrics':['AP (sklearn average_precision_score)','AUROC','F1'],'aggregation':'Per-region values and equal-region macro mean; pooled values secondary','threshold':'One global F1 threshold from validation only, highest threshold on a tie','checkpoint':'Highest validation region-macro AP; earliest epoch on a tie','test_policy':'No test-based checkpoint, threshold or hyperparameter selection','outputs':['every-sample validation/test predictions','source window IDs, MMSI, region and labels','normalizer train provenance','actual checkpoint and data hashes','per-region and macro metrics']},
 'pilot':{'stage':'Pipeline validation, one seed; no final multi-seed paper claim','backbones':['tcn','gru','transformer'],'input_groups':['raw','plain_context','plain_affine_context','context'],'seed':0,'epochs':8,'hidden':32,'dropout':.1,'optimizer':'AdamW','learning_rate':.002,'weight_decay':.01,'batch_size':128,'clip_grad_norm':5,'cpu_threads':4,'subset_per_region':{'train':240,'val':80,'test':80},'subset_class_fraction':.4,'subset_reused_for_all_models_and_views':True,'normalizer':'Training-subset valid steps only; padding zeroed after normalization','heldout_domain_status':'Regions are represented in training; this pilot establishes vessel-heldout paired mechanics, not unseen-region generalization'},
 'formal_next_experiments':['Multiple paired seeds and confidence intervals','Capacity-matched raw controls','Unseen-region rotation with source-only calibration','Generator-shape holdout and corruption/group robustness','Independent PSA/consistency and relational-task ablations'],
 'historical_results':'Historical data, figures, predictions and weights retain their own data-version identity; this protocol creates new predictions without editing historical scores'}
path=OUT/'benchmark_protocol.json'
if path.exists():raise RuntimeError('Refusing to overwrite frozen protocol')
path.write_text(json.dumps(config,indent=2,ensure_ascii=False))
print('FROZEN',path,sha(path),flush=True)
